import{z as o,x as B,o as n,c as d,q as s,j as r,D as E,d as i,s as A,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"财政刺激与 HANK","description":"","frontmatter":{"title":"财政刺激与 HANK","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/fiscal-hank.md","filePath":"econ/fiscal-hank.md","lastUpdated":1791063341000}'),p={name:"econ/fiscal-hank.md"};function m(D,a,c,h,C,f){const t=B("Mermaid");return n(),d("div",null,[a[2]||(a[2]=s('<h1 id="财政刺激与-hank" tabindex="-1">财政刺激与 HANK <a class="header-anchor" href="#财政刺激与-hank" aria-label="Permalink to &quot;财政刺激与 HANK&quot;">​</a></h1><div class="epigraph"><p>一次总付的乘数取决于给谁、债由谁持有、以及收入循环碰到多高的 MPC——李嘉图在不完全市场里不是默认。</p><footer>—— Oh and Reis, Targeted Transfers and the Macroeconomic Effects of Fiscal Stimulus, JME 2012；Kaplan and Violante 刺激支付；McKay and Reis 自动稳定器</footer></div><p><a href="/econ/heterogeneous-mpc">上一课</a>给出加权 MPC。财政课在代表性主干里已有乘数与李嘉图。本课缺口是 <strong>HANK 里的刺激</strong>：转移的指向与赤字融资改变一般均衡。不重估叙事军费，不重写 MPC 分箱。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RANK 李嘉图：减税被未来税抵消，欧拉不动。HANK：今天的支票进高 MPC 口袋，未来税若落在低 MPC 或尚未出生的人身上，当期 \\(C\\) 升。Oh–Reis：指向性转移可以有可观的产出效应。政府购买仍走劳动需求与收入循环，但挤出经利率的强度取决于谁是储蓄者。缺口是把「乘数」从单一数字改成<strong>工具 × 分配 × 规则</strong>的函数。</p><p><span class="marginnote">Oh and Reis, <em>JME</em> 59(6), 2012。McKay and Reis, <em>JPE</em> 2016 自动稳定器。Hagedorn, Manovskii and Mitman 对 HANK 乘数的定量争论。Auclert, Rognlie and Straub 的序列空间财政。</span></p><p><span class="marginnote">李嘉图等价是一个思想实验：政府今天减税、明天必然加税，理性人会把省下的税存起来等将来交，于是刺激等于零。它成立的前提是人人都能自由借贷并做长期规划——现实中近半家庭月月光、存不下钱，所以同样的减税立刻变成消费。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实验：同样规模的赤字，比较（i）给约束家庭的转移，（ii）给平均家庭，（iii）政府消费。融资：短期债、长期债、通胀税、延迟的累进税。货币规则：利率是否对产出缺口反应，决定挤出。ZLB 下 RANK 已有大乘数；HANK 在正利率下也可以因 MPC 而不小。与叙事/LP 对照：加总 IRF 是混合处理，模型用来拆指向。</p>',9)),(n(),r(l,null,{default:E(()=>[A(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20TR%5B%22%E8%BD%AC%E7%A7%BB%E7%BB%99%E8%B0%81%22%5D%20--%3E%20MPC%5B%22%E6%88%AA%E9%9D%A2%20MPC%22%5D%0A%20%20MPC%20--%3E%20DEM%5B%22%E9%9C%80%E6%B1%82%22%5D%0A%20%20FIN%5B%22%E8%B0%81%E6%8C%81%E6%9C%89%E5%85%AC%E5%80%BA%20%2F%20%E8%B0%81%E7%BA%B3%E7%A8%8E%22%5D%20--%3E%20REDIST%5B%22%E5%86%8D%E5%88%86%E9%85%8D%22%5D%0A%20%20REDIST%20--%3E%20DEM%0A%20%20RULE%5B%22%E8%B4%A7%E5%B8%81%E8%A7%84%E5%88%99%22%5D%20--%3E%20CROWD%5B%22%E6%8C%A4%E5%87%BA%E6%88%96%E5%AE%B9%E7%BA%B3%22%5D%0A%20%20DEM%20--%3E%20Y%5B%22%E4%BA%A7%E5%87%BA%22%5D%0A%20%20CROWD%20--%3E%20Y%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"自动稳定器（失业救济、累进税）是状态依存的指向性转移，不必等新立法——与后课 UI 接口。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"数字实例：发 1000 亿元给 MPC 为 0.5 的受约束家庭，第一轮就有 500 亿变成消费；同样 1000 亿给 MPC 为 0.05 的富裕家庭，只花掉 50 亿。指向不同，同样的赤字规模效果差一个量级。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[i("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"机制是再分配加收入循环。公债是某些家庭的流动性资产：发债可以放松贫流动性约束（政府债供给），同时提高未来税负担。符号取决于校准。货币紧缩若伴随财政扩张，间接效应可能打架。开放经济漏出、进口边际，本课只点名。",-1)),(n(),r(l,null,{default:E(()=>[A(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20DEF%5B%22%E8%B5%A4%E5%AD%97%E5%88%BA%E6%BF%80%22%5D%20--%3E%20BOND%5B%22%E5%8F%91%E5%80%BA%22%5D%0A%20%20BOND%20--%3E%20LIQ%5B%22%E5%85%AC%E5%80%BA%E8%BF%9B%E5%85%A5%E5%AE%B6%E5%BA%AD%E8%B5%84%E4%BA%A7%E7%AB%AF%22%5D%0A%20%20LIQ%20--%3E%20RELAX%5B%22%E6%94%BE%E6%9D%BE%E6%B5%81%E5%8A%A8%E6%80%A7%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20RELAX%20--%3E%20CUP%5B%22%E5%BD%93%E6%9C%9F%E6%B6%88%E8%B4%B9%E4%B8%8A%E5%8D%87%22%5D%0A%20%20BOND%20--%3E%20TAX%5B%22%E6%9C%AA%E6%9D%A5%E7%A8%8E%E8%B4%9F%E4%B8%8A%E5%8D%87%22%5D%0A%20%20TAX%20--%3E%20CUT%5B%22%E9%A2%84%E6%9C%9F%E6%B6%88%E8%B4%B9%E4%B8%8B%E8%B0%83%22%5D%0A%20%20CUP%20--%3E%20NET%5B%22%E5%87%80%E6%95%88%E5%BA%94%E7%AC%A6%E5%8F%B7%E4%B8%8D%E5%AE%9A%22%5D%0A%20%20CUT%20--%3E%20NET%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p><span class="marginnote">公债的两面可以类比借新还旧：新增政府债让持债家庭觉得自己更有钱（资产端增加），但同一笔债记在未来纳税人头上（负债端同步增加）。净效应是让人敢花钱还是捂紧钱包，取决于哪一头的人边际消费倾向更高。</span></p><p>与识别课：Ramey 军费冲击不是一次总付，HANK 的转移实验不能直接套军费 IRF 当校准靶而不改工具。</p><p><span class="marginnote">主干<a href="/econ/fiscal-multiplier">财政乘数</a>已有代表性叙述。本课只补异质缺口，不重写 IS 会计。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写最优公共债务水平（可持续性在金融摩擦单元）。不把产业政策当刺激。主权利差、违约是 Eaton–Gersovitz 以后的课。也不做量化交易策略。</p><p>后课默认：HANK 财政乘数依赖指向与融资；李嘉图不是默认。下一课：把分配的长期运动接到 \\(r\\) 与 \\(g\\)，而不只是一次支票。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>刺激的乘数是指向 × MPC × 融资 × 货币规则。</li><li>不完全市场打破默认李嘉图。</li><li>加总财政 IRF 混合了工具，模型负责拆解。</li><li>出处：Oh and Reis, <em>JME</em> 2012；Kaplan–Violante；McKay and Reis, <em>JPE</em> 2016。</li></ul>',8))])}const M=o(p,[["render",m]]);export{P as __pageData,M as default};
